export type SwatchDraft = { name: string; colors: string[] };
export type StoredDraft = SwatchDraft & { id: number };

function validate(draft: SwatchDraft): SwatchDraft {
  if (typeof draft !== "object" || draft === null ||
      typeof draft.name !== "string" || draft.name.trim() === "" ||
      !Array.isArray(draft.colors) || draft.colors.length === 0 ||
      draft.colors.some(color => typeof color !== "string" || !/^#[0-9A-Fa-f]{6}$/.test(color))) {
    throw new TypeError("Invalid draft");
  }
  return { name: draft.name.trim(), colors: [...draft.colors] };
}

function copy(draft: StoredDraft): StoredDraft {
  return { ...draft, colors: [...draft.colors] };
}

export class DraftShelf {
  private readonly drafts: StoredDraft[] = [];
  private nextId = 1;

  add(draft: SwatchDraft): StoredDraft {
    const checked = validate(draft);
    const stored: StoredDraft = { id: this.nextId++, ...checked };
    this.drafts.push(stored);
    return copy(stored);
  }

  getAll(): StoredDraft[] {
    return this.drafts.map(copy);
  }

  remove(id: number): boolean {
    if (!Number.isInteger(id) || id <= 0) throw new RangeError("Invalid id");
    const index = this.drafts.findIndex(draft => draft.id === id);
    this.drafts.splice(index, 1);
    return index >= 0;
  }
}

