import { DraftShelf, type SwatchDraft } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function captures(fn: () => void): unknown {
  try { fn(); } catch (error) { return error; }
  return undefined;
}

const shelf = new DraftShelf();
deepEqual(shelf.getAll(), [], 'initial shelf empty');
const draft: SwatchDraft = { name: '  Sunset  ', colors: ['#Aa00fF', '#000000', '#Aa00fF'] };
const first = shelf.add(draft);
deepEqual(first, { id: 1, name: 'Sunset', colors: ['#Aa00fF', '#000000', '#Aa00fF'] }, 'valid draft stored');
draft.name = 'Changed';
draft.colors[0] = '#FFFFFF';
first.name = 'Mutated';
first.colors.push('#123456');
deepEqual(shelf.getAll()[0], { id: 1, name: 'Sunset', colors: ['#Aa00fF', '#000000', '#Aa00fF'] }, 'input and output are copied');

const all = shelf.getAll();
all[0].colors[0] = '#FFFFFF';
all.length = 0;
assert(shelf.getAll().length === 1 && shelf.getAll()[0].colors[0] === '#Aa00fF', 'getAll is deeply defensive');

const malformed: unknown[] = [
  null,
  { name: '', colors: ['#000000'] },
  { name: '   ', colors: ['#000000'] },
  { name: 4, colors: ['#000000'] },
  { name: 'X', colors: [] },
  { name: 'X', colors: '#000000' },
  { name: 'X', colors: ['#00000'] },
  { name: 'X', colors: ['#GG0000'] },
  { name: 'X', colors: ['#000000', 7] }
];
for (const value of malformed) {
  assert(captures(() => shelf.add(value as SwatchDraft)) instanceof TypeError, 'malformed draft rejected');
}
const second = shelf.add({ name: 'Ocean', colors: ['#0011aa'] });
assert(second.id === 2, 'failures do not consume ids');
assert(shelf.remove(99) === false, 'valid absent id returns false');
assert(shelf.remove(1) === true, 'existing draft removed');
assert(shelf.add({ name: 'Forest', colors: ['#00FF00'] }).id === 3, 'ids are never reused');
deepEqual(shelf.getAll().map(item => item.name), ['Ocean', 'Forest'], 'insertion order retained after removal');
for (const id of [0, -2, 1.2, Infinity, NaN]) {
  assert(captures(() => shelf.remove(id)) instanceof RangeError, 'malformed removal id rejected');
}

